let isDropdownVisible = false;
let outsideClickHandler = null;

function toggleDropdown(buttonElement) {
  const dropdownContent = document.getElementById("dropdown-content");
  const chevron = buttonElement.querySelector('.chevron');
  if (!isDropdownVisible) {
    dropdownContent.style.display = "block";
    dropdownContent.style.opacity = "1";
    buttonElement.setAttribute('aria-expanded', 'true');
    if (chevron) chevron.classList.add('rotate-down');
    isDropdownVisible = true;

    outsideClickHandler = function(event) {
      if (!dropdownContent.contains(event.target) && !buttonElement.contains(event.target)) {
        dropdownContent.style.display = "none";
        dropdownContent.style.opacity = "0";
        buttonElement.setAttribute('aria-expanded', 'false');
        if (chevron) chevron.classList.remove('rotate-down');
        isDropdownVisible = false;
        document.removeEventListener('click', outsideClickHandler);
        outsideClickHandler = null;
      }
    };
    setTimeout(function() {
      document.addEventListener('click', outsideClickHandler);
    }, 0);
  } else {
    dropdownContent.style.display = "none";
    dropdownContent.style.opacity = "0";
    buttonElement.setAttribute('aria-expanded', 'false');
    if (chevron) chevron.classList.remove('rotate-down');
    isDropdownVisible = false;
    if (outsideClickHandler) {
      document.removeEventListener('click', outsideClickHandler);
      outsideClickHandler = null;
    }
  }
}
function openTranslatedUrl(languageCode, isOriginalLanguage = false) {
  if (isOriginalLanguage) {
    const originalUrl = "https://www.somervillema.gov" + window.location.pathname;
    window.open(originalUrl, '_blank');
    return;
  }
  const pathName = window.location.pathname;
  const googleTranslateUrl = `https://www-somervillema-gov.translate.goog${pathName}?_x_tr_sl=auto&_x_tr_tl=${languageCode}&_x_tr_hl=en&_x_tr_pto=wapp`;
  window.open(googleTranslateUrl, '_blank');
}

